package com.vandorlabs.vehicle.core;
public final class OwnershipSourceRetryTest {
 private static int checks;private static void need(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 public static void main(String[] args){long first=7123456,deadline=first;need(OwnershipSourceRetry.due(true,deadline,first,false),"first dirty request is immediate");deadline=OwnershipSourceRetry.after(first);need(!OwnershipSourceRetry.due(true,deadline,first+1499999999L,false),"existing server1500ms throttle cannot cause a busy retry");need(!OwnershipSourceRetry.due(true,deadline,deadline-1,false),"retry waits full interval");need(OwnershipSourceRetry.due(true,deadline,deadline,false),"suppressed request retries after2s");need(!OwnershipSourceRetry.due(true,deadline,deadline+3000000000L,true),"active Source decoder is not restarted");need(OwnershipSourceRetry.due(true,deadline,deadline+3000000000L,false),"abandoned decoder does not consume the pending retry");need(!OwnershipSourceRetry.due(false,deadline,deadline+3000000000L,false),"successful full install clears pending work");long wrap=Long.MAX_VALUE-100,after=OwnershipSourceRetry.after(wrap);need(!OwnershipSourceRetry.due(true,after,wrap,false)&&OwnershipSourceRetry.due(true,after,after,false),"monotonic deadline tolerates long wrap");System.out.println("Ownership Source retry policy PASS checks="+checks+" immediate/bounded2s/existing throttle/active decoder/success/wrap; no references");}
}
